 d=read(OUT/'delivery-summary.json');perf=read(OUT/'performance.json');plan=read(OUT/'optimization-plan.json');grid=read(OUT/'physical-grid.json');ver=read(OUT/'verification.json');controls=read(OUT/'packing-controls.json');search=read(OUT/'search-summary.json');coupled=read(OUT/'coupled-summary.json')
 physical=grid['rows'];counts=Counter(r['classification'] for r in physical);models=d['models'];best=models[0];c=best['summary'];old=d['R319'];inh=d['inherited']
