 fig,ax=plt.subplots(figsize=(7,3),layout='constrained');x=np.arange(3);cold=[perf['table'][s]['process-cold']['total_seconds']['median'] for s in ['100','200','all']];warm=[perf['table'][s]['geometry-invalidated']['total_seconds']['median'] for s in ['100','200','all']];cached=[perf['table'][s]['exact-geometry-cached-light-change']['total_seconds']['median'] for s in ['100','200','all']]
