 lines += ['', '| Model | Black (7) Emax px | Red (11) Emax px | Yellow (4) Emax px |', '|---|---:|---:|---:|']
 for label,cc in colorrows.items():lines.append('| '+label+' | '+' | '.join(fmt(cc[k]['emax_px']) for k in ['black','red','yellow'])+' |')
 lines += ['', 'All seven black reflections remain in the maximum; there is no color-dependent dropping or weighting.', '', 'Different-map maxima are conditional comparisons, not identified geometric gains. The selected-model assignment controls evaluate the historical and new maps at identical geometry and explicitly mark assignment effects as non-geometric. All per-core fractions, paper occupation, missing brackets and internal core crossings remain in the exports. A low dual-claim count does not establish correct ownership. There are no invented black-bead silhouettes or hidden outlines.', '', 'The centerline-control export is a one-coefficient intervention with its matching uncorrected parent retained in `centerline-controls.json`; coupled final changes are not mislabeled as an isolated centerline benefit. The photograph overlays show actual visible owner edges (including modeled holes/occlusion edges), observed yellow circles, predicted magenta crosses and displacement vectors. Only supported material-to-paper brackets are scored as exterior evidence.', '', '![Physical coverage](r320/results/physical-search.png)', '', '## Contact and packing diagnosis','']
 for v in ver['models']:
  lines.append(f'**{v["label"]}**: {v["witnesses"]} independently checked positive support witnesses; maximum position seam gap {v["summary"]["closure"]["center_endpoint_gap"]:.3g} units, frame gap {v["summary"]["closure"]["orientation_endpoint_gap"]:.3g}.');lines.append('')
  for g in v['neighbors']:lines.append(f'- Offset+{g["offset"]}: median glass-clearance bracket [{g["lower_median"]:.5f}, {g["upper_median"]:.5f}] units; {g["near_contacts_upper_le_002r"]} pairs have certified upper gap≤0.02r, {g["small_gaps_upper_le_01r"]}≤0.10r. All seam-crossing records are retained.')
  lines.append('')
 lines += ['Clearance lower bounds come from optimized separating planes; upper bounds come from explicit actual-glass surface endpoints checked by the implicit shape. They are not mislabeled exact distances. Neighbor classes need not all contact simultaneously. Actual tangency is not asserted from a finite tolerance.', '', 'Straight-axis packing controls hold the same rigid profiles and test P/H0.95…1.30, with R/R0=1 and1/0.96. They isolate local staircase packing from the curved photographic centerline and are not closed bracelets. Both the control classifications and actual penetration witnesses are retained. At P/H=1.00 every tested straight thickness (axial0.65/0.85/1.05/1.25) demonstrates interpenetration, at both R0 and R0/0.96. At P/H=1.05 all eight controls certify separation. Thus even the straight rounded rigid shapes need a small rise allowance in these tests. On the curved photo centerline the coarse construction never rescued a failed R0 input by increasing R up to1.16R0; all169 certified coarse inputs already passed at R0. The coarse full-scene failures show a contact/circumference tension; they do not prove the requested physical model impossible, because phase, major shape, profile uncertainty and untested packing constructions remain.', '', '## Performance: measured, not scaled from R319','', 'Seconds below are geometry-invalidated medians (three configurations). Bodies remain2200/2600/2800 at every scope; targets are100,200 or all bodies. The second evaluation changes radius and a0.25px centerline harmonic, invalidating geometry and the centerline cache. Operation groupings are deliberately honest:', '', '| Operation | 100 | 200 | All |','|---|---:|---:|---:|']
 for key,title in [('positions_orientations_and_initial_acceleration','Positions/orientations + initial spatial trees'),('all_body_nonintersection','All-body rigid contact/nonintersection'),('native_lattice_construction','Target native lattice'),('camera_rays_and_normals','Camera rays + surface normals'),('visible_boundary_extraction','Visible boundary extraction from first hits'),('shadows_and_illumination','Shadow queries + illumination'),('reflection_localization','Connected principal reflection localization'),('photographic_rays_outlines_ownership','Evidence rays + outline/ownership diagnostics'),('objective','Frozen-map Euclidean objective')]:
  lines.append('| '+title+' | '+' | '.join(f'{perf["table"][s]["geometry-invalidated"]["operations"][key]["median"]:.5f}' for s in ['100','200','all'])+' |')
 lines.append('| **Total** | '+' | '.join(f'**{perf["table"][s]["geometry-invalidated"]["total_seconds"]["median"]:.3f}**' for s in ['100','200','all'])+' |')
 lines += ['', '| Scope | Cold median / p95 | Changed geometry median / p95 | Exact-cache light median / p95 | Camera pixels range | Peak RSS MiB |','|---|---:|---:|---:|---:|---:|']
 for s in ['100','200','all']:
  tab=perf['table'][s];vals=[]
  for mode in ['process-cold','geometry-invalidated','exact-geometry-cached-light-change']:
   v=tab[mode]['total_seconds'];vals.append(f'{v["median"]:.3f} / {v["p95"]:.3f}')
  rr=tab['process-cold']['camera_rays'];lines.append(f'| {s} | '+ ' | '.join(vals)+f' | {rr["minimum"]:.0f}…{rr["maximum"]:.0f} | {max(t["peak_rss_mib"] for t in tab.values()):.1f} |')
 lines += ['', f'Hardware: **{perf["hardware"]["cpu_model"]}**; {perf["hardware"]["logical_cpus"]} logical CPUs exposed, one numerical/OpenMP thread, one process at a time. Peak RSS is a process high-water mark, not exclusive allocation per operation. Setup median{perf["setup_seconds"]["median"]:.3f}s is outside the evaluation total. C++ shared libraries were precompiled on disk; no compiler cold-start claim. Empirical p95 from three configurations is not a calibrated tail estimate.', '', f'The contact-derived packing construction is an additional measured cost: median{perf["packing_solver_seconds"]["median"]:.4f}s, p95{perf["packing_solver_seconds"]["p95"]:.4f}s over the physical grid. The measured complete physical-grid batch, including actual-solid fallback and serialization, averages{perf['packing_solver_seconds']['observed_batch_seconds_per_trial']:.4f}s/input; the expected plan uses this aggregate cost rather than pretending the cheap median describes a mixed coarse grid. Near-contact/unresolved proposals can be much more expensive than the already-certified scenes in the rendering table. The packing batch partly overlapped preliminary timing work, so it is a measured campaign cost rather than an isolated kernel benchmark; the final rendering table was repeated sequentially. Full-scope camera rays dominate; shadows are second, followed by photographic evidence and lattice assembly. The objective arithmetic itself is negligible.', '', 'Local timing includes the fixed R319 geometry patch, while all-bracelet timing additionally measures the historical447 positive-interior regions and paper cues. Scope100/200 therefore means modeled target interval, not100/200 measured highlights or100/200 fully observed bead contours. Unknown camera/shadow cases, actual observation counts and missing predictions are explicit in the machine-readable records. No missing prediction is rewarded. Because the benchmark photo geography is fixed from R319, some observations can map outside the current count family’s 100/200 target interval; those missing predictions remain explicit. These runs benchmark kernels, not successful cohort fits. The optical pilot separately expands the target-box union to include every frozen mapped owner, so changing count cannot discard difficult observations.', '', 'Exact caching helps light-only changes but cannot be charged to count/radius/axial/centerline changes. Promising improvements are batching/accelerating exact camera intersection, native lattice construction and grouping, followed by shadow-query reuse. Preserve original-kernel comparisons and nonintersection certification. Parallel independent families are plausible, but no unmeasured parallel speedup is credited.', '', '![Measured performance](r320/results/performance.png)', '', '## Later optimization plan','', '| Phase | Count families | Radius/axial combinations | Probes/iterations per family | Expected evaluations | Scope | Median / conservative sec per evaluation* | Low / expected / high hours |','|---|---:|---:|---:|---:|---|---:|---:|']
 for p in plan['phases']:
  ss=p['scenarios'];lines.append(f'| {p["phase"]} | {p["count_families"]} | {p["radius_axial_combinations"]} | {p["probes_or_iterations_per_family"]} | {p["expected_evaluations"]} | {p["scope"]} | {ss["expected"]["fast_evaluation_seconds"]+ss["expected"]["packing_seconds"]:.3f} / {ss["high"]["fast_evaluation_seconds"]+ss["high"]["packing_seconds"]:.3f} | '+ ' / '.join(f'{ss[k]["total_seconds"]/3600:.2f}' for k in ['low','expected','high'])+' |')
 lines += ['', '*Per-evaluation costs include packing. The independent-verification phase has a separately declared **unmeasured10× original-kernel allowance**, not an invented benchmark. Counts of Jacobian evaluations are separate from optimizer proposals. Initial count sampling uses49 families roughly25 apart across2000…3200, followed by exact winding-transition neighbors. Low/high scenarios halve/double evaluation counts and use observed timing extrema/packing p95; they are planning scenarios, not confidence bounds or convergence guarantees.', '', '**Serial total: '+ ' / '.join(f'{plan["serial_totals_seconds"][k]/3600:.2f}h' for k in ['low','expected','high'])+' (low / expected / high).** Each phase uses M×measured evaluation cost plus per-family cold setup. No linear extrapolation from22 reflections, from100 bodies, or from N is used. More ambitious dense photo evidence, other count/radius extremes and independent full-field original-kernel verification still need their own timings. This plan does not authorize or launch another round.', '', '## Verification and remaining limitations','', f'Four focused contracts cover support dimensions, both-handed closure across integer winding changes, centerline budget/zero recovery and forbidden free orientation/seam variables. Independent selected-model audits check {sum(v["witnesses"] for v in ver["models"])} exact support witnesses, analytic staircase normals, {sum(v["python_rays"] for v in ver["models"])} original Python camera rays and original Python shadow intensities. Every selected +1/+6/+7 pair, including the seam, receives clearance brackets. All trial cohorts, Euclidean maxima, hashes, performance-row counts and static artifact links are checked separately.', '', 'The old results and original image are unchanged. Preliminary overlapping-work timings, a caught duplicate-key failure and a caught benchmark-loop-control failure are archived and excluded from the final table; the final six-row/cache-mode contract prevents silently losing a mode. A separate neighbor-clearance check caught support-gradient endpoints falling into the annular bore at degenerate axial normals; the initial distance artifacts were rejected and archived. Corrected actual-glass support endpoints now satisfy explicit implicit-surface assertions before any upper distance is reported. An initial coupled-search assumption about handedness also failed before new trials; the retained correction selects the actually available complete-map parent in each count family.', '', 'Remaining obstacles: correct count/correspondence, physically credible packing near one thickness on a curved centerline, undersized visible surfaces in the current near-rise candidate, uncertain glass optics and illumination, and finite sampling/principal-lobe changes. A positive support certificate establishes nonintersection, not mechanical equilibrium or real contact forces. The small centerline corrections do not establish a recovered centerline. No final geometry or color pattern is adopted.', '', 'Start04:10:01UTC; scientific cutoff04:34:01UTC; delivery deadline04:40:01UTC on2026-10-18. Actual commit/push receipt is in `r320/results/delivery.json`. **Stop for review.**','']
 allparams=[r['parameters'] for r in allrows]+[r['parameters'] for r in physical]
 ranges={k:dict(minimum=min(p[k] for p in allparams),maximum=max(p[k] for p in allparams)) for k in ['radius','axial','phase','s0']}
 extra=['', 'Actual principal-parameter ranges including refinement: radius '+fmt(ranges['radius']['minimum'],6)+'…'+fmt(ranges['radius']['maximum'],6)+' units; axial '+fmt(ranges['axial']['minimum'],6)+'…'+fmt(ranges['axial']['maximum'],6)+'. Global phase '+fmt(ranges['phase']['minimum'],6)+'…'+fmt(ranges['phase']['maximum'],6)+'rad; station '+fmt(ranges['s0']['minimum'],4)+'…'+fmt(ranges['s0']['maximum'],4)+'px. See [actual search ranges](r320/results/actual-search-ranges.json) for distinct-value counts.', '', '| Fixed-map coupled family | Parent Emax px | Best complete-map Emax px | Best L/(WH) | Centerline displacement px |', '|---|---:|---:|---:|---:|']
